import fs from "fs";
import path from "path";

const root = path.resolve(import.meta.dirname, "..");
const gzPath = path.join(root, "src", "lib", "demo", "snapshot.json.gz");
const outPath = path.join(root, "src", "lib", "demo", "snapshot-data.ts");

const gz = fs.readFileSync(gzPath);
const b64 = gz.toString("base64");
const source = [
  "// Auto-generated by scripts/embed-demo-snapshot.mjs — do not edit.",
  `export const SNAPSHOT_GZ_BASE64 = "${b64}";`,
  "",
].join("\n");

fs.writeFileSync(outPath, source);
console.log({
  gzBytes: gz.length,
  outChars: source.length,
  outMB: Number((source.length / 1024 / 1024).toFixed(2)),
  outPath,
});
